import {
  type CreateStorageRequestInput,
  type StorageRequest as StorageRequestDto,
  toCalendarDate,
} from '@deadspace/shared';
import type { PrismaClient } from '../db.js';
import type { Prisma, StorageRequest } from '../generated/prisma/client.js';
import type { StorageMatchRequest } from '../matching/warehouse.js';

/** Maps validated input to columns. The *Geog column is generated by the database. */
export function toStorageRequestCreateData(input: CreateStorageRequestInput): Prisma.StorageRequestCreateInput {
  const { location, ...rest } = input;
  return {
    ...rest,
    locationLabel: location.label,
    locationLat: location.lat,
    locationLng: location.lng,
  };
}

export function createStorageRequest(prisma: PrismaClient, input: CreateStorageRequestInput): Promise<StorageRequest> {
  return prisma.storageRequest.create({ data: toStorageRequestCreateData(input) });
}

export function findStorageRequestById(prisma: PrismaClient, id: string): Promise<StorageRequest | null> {
  return prisma.storageRequest.findUnique({ where: { id } });
}

/** Row → API shape: location regrouped, Decimal money as number, calendar dates as YYYY-MM-DD. */
export function toStorageRequestDto(row: StorageRequest): StorageRequestDto {
  return {
    id: row.id,
    status: row.status,
    companyName: row.companyName,
    contactName: row.contactName,
    contactEmail: row.contactEmail,
    location: { label: row.locationLabel, lat: row.locationLat, lng: row.locationLng },
    maxDistanceMiles: row.maxDistanceMiles,
    pallets: row.pallets,
    startDate: toCalendarDate(row.startDate),
    endDate: toCalendarDate(row.endDate),
    needsTemperatureControl: row.needsTemperatureControl,
    needsFoodGrade: row.needsFoodGrade,
    maxBudgetTotal: row.maxBudgetTotal?.toNumber() ?? null,
    notes: row.notes,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

/** Row → the plain request the pure matcher reads (Decimal money as number, dates as UTC midnights). */
export function toStorageMatchRequest(row: StorageRequest): StorageMatchRequest {
  return {
    maxDistanceMiles: row.maxDistanceMiles,
    pallets: row.pallets,
    startDate: row.startDate,
    endDate: row.endDate,
    needsTemperatureControl: row.needsTemperatureControl,
    needsFoodGrade: row.needsFoodGrade,
    maxBudgetTotal: row.maxBudgetTotal?.toNumber() ?? null,
  };
}
